package dev.aivillages.e2e.paralleld;
import java.nio.file.*;
import java.util.*;
import com.google.gson.*;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.*;
/** Unqualified mock diagnostics only. Never included in the final native/client qualification schedule. */
public final class DComponentDiagnosticGameTests {
 DChestCourierScene previous;DComponentCase current;GameTestHelper helper;ServerPlayer a,b;List<JsonObject> cases;Path root;
 @GameTest(maxTicks=20000)
 public void diagnoseNativeFixturesWithoutClientCredit(GameTestHelper h){helper=h;root=Path.of(System.getProperty("cognitivecraft.parallelD.evidence"));a=h.makeMockServerPlayerInLevel();b=h.makeMockServerPlayerInLevel();b.setUUID(UUID.randomUUID());try(var in=getClass().getResourceAsStream("/d10-scenarios.json")){cases=new ArrayList<>();String group=System.getProperty("cognitivecraft.parallelD.diagnosticGroup","storage");for(var row:JsonParser.parseString(new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject().getAsJsonArray("cases")){var s=row.getAsJsonObject();if(s.get("group").getAsString().equals(group))cases.add(s);}}catch(Exception e){throw new RuntimeException(e);}next(0);}
 void next(int i){if(i==cases.size()){previous.identities.close();DChestCourierScene.when(previous.level,previous.store.closeAsync(),v->helper.succeed());return;}JsonObject s=cases.get(i);var x=s.getAsJsonArray("origin");var pos=new BlockPos(x.get(0).getAsInt(),x.get(1).getAsInt(),x.get(2).getAsInt());for(int cx=(pos.getX()>>4)-1;cx<=(pos.getX()+20>>4)+1;cx++)for(int cz=(pos.getZ()>>4)-1;cz<=(pos.getZ()+25>>4)+1;cz++){helper.getLevel().setChunkForced(cx,cz,true);helper.getLevel().getChunkAt(new BlockPos(cx*16,pos.getY(),cz*16));}a.setPos(pos.getX()+14.5,pos.getY(),pos.getZ()+7.5);b.setPos(pos.getX()+15.5,pos.getY(),pos.getZ()+4.5);helper.runAfterDelay(40,()->DChestCourierScene.open(helper.getLevel(),pos,a,root.resolve(s.get("id").getAsString()).resolve("setup"),s.get("id").getAsString(),previous,s.get("id").getAsString(),base->{previous=base;helper.runAfterDelay(40,()->{current=switch(s.get("group").getAsString()){case "storage"->new DComponentStorage(s,base,root.resolve(s.get("id").getAsString()));case "courier"->new DComponentCourier(s,base,root.resolve(s.get("id").getAsString()));case "handoff"->new DComponentHandoff(s,base,root.resolve(s.get("id").getAsString()));default->throw new IllegalStateException("diagnostic group");};current.prepare(()->helper.runAfterDelay(4,()->{current.facts.put("diagnostic_mock_players",true);current.ready();if(current instanceof DComponentStorage storage && storage.number==1){a.setPos(storage.primary.getX()+.5,storage.primary.getY(),storage.primary.getZ()-2.5);a.setYRot(0);a.setXRot(25);}current.execute(current instanceof DComponentStorage storage && storage.number==9?b:a);step(i,0);}));});}));}
 void step(int i,int ticks){helper.assertTrue(ticks<1600,"bounded native diagnostic");if(current.terminal){next(i+1);return;}if(current.phase.startsWith("AWAIT_") && !current.phase.equals("AWAIT_NATIVE_SAVE"))current.interfere(b,"diagnostic");if(current instanceof DComponentCourier courier && courier.number>=7 && courier.number<=9 && !courier.interfered && courier.phase.equals("MOVING_TO_DESTINATION") && courier.base.route.observation().travelBlocks()>2)courier.interfere(b,"diagnostic");if(current.phase.equals("AWAIT_NATIVE_SAVE")){current.operation("DIAGNOSTIC_NO_CLIENT_RESTART_CREDIT",null);current.complete(Map.of("disposition","INCONCLUSIVE_NO_CONNECTED_CLIENTS"));}else current.tick();helper.runAfterDelay(1,()->step(i,ticks+1));}
}
